# name = config.threshold
# descr = read threshold from config and log warnings on overflow

use strict;
use warnings;
use perlmod.load qw| base.logs |;

sub init_code {
    my $cfg = <[base.config]>->();

    my $threshold = <[base.config]>->( 'threshold', 30 );

    ## load the threshold into the module namespace
    $::{'_threshold'} = $threshold;

    ## log a warning if the threshold is exceeded
    if ( $threshold > 30 ) {
        <[base.logs]>->( 2, '%s threshold exceeded (got %d, max %d)',
            qw| config.threshold |, $threshold, 30 );
    }

    return { 'mode' => qw| true |, 'data' => $threshold };
}

sub run {
    return 1;
}
